const KTV = (() => {
  const NAVY = '#16213A';
  function bg(ctx, titel) { ctx.fillStyle = NAVY; ctx.fillRect(0, 0, 1920, 1080); if (titel) { ctx.fillStyle = '#E8E2D6'; ctx.font = '600 30px "Source Sans 3", sans-serif'; ctx.textAlign = 'left'; ctx.fillText(titel, 40, 50); } }
  function label(ctx, t, x, y, c = '#C9B48A', size = 22, al = 'center') { ctx.fillStyle = c; ctx.font = `500 ${size}px "IBM Plex Mono", monospace`; ctx.textAlign = al; ctx.fillText(t, x, y); }
  function grond(ctx, x0, x1, y) { ctx.strokeStyle = '#5A6680'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(x0, y); ctx.lineTo(x1, y); ctx.stroke(); }
  // referentie-omtrek tekenen: px -> cm (K van het dier), uitgelijnd op x0 (plaat-px die op cm 0 valt) of op de neus (max x)
  function omtrek(ctx, naam, P, x, y, s, o = {}) { const O = KTV_OMTREK[naam]; if (!O) return; const K = o.K || P.D.K; let ox;
    if (o.x0 != null) ox = o.x0; else { const nx = Math.max(...O.p.map(p => p[0])); ox = nx - (o.neus ?? 0) * K; }
    const k = o.kijk || 1;
    ctx.save(); ctx.translate(x, y); ctx.scale(s * k, s); ctx.beginPath(); O.p.forEach(([px, py], i) => { const c = [(px - ox) / K, (py - O.g) / K]; i ? ctx.lineTo(c[0], c[1]) : ctx.moveTo(c[0], c[1]); }); ctx.closePath();
    ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.strokeStyle = o.c || '#F2C14E'; ctx.lineWidth = o.lw || 2.2; ctx.setLineDash(o.dash || [7, 5]); ctx.stroke(); ctx.setLineDash([]); ctx.restore(); }
  // neuspunt (x, cm) van de pop in een houding
  const neusX = (P, o) => { const I = P.info(o); const n = I.eind('kop'); return n[0] - (P.D.anker || 0); };
  function overlay(ctx, P, items, titel) { bg(ctx, titel); const n = items.length; const w = 1920 / n;
    items.forEach((it, i) => { const s = it.s || (w * 0.82) / 200; const x = w * i + w * 0.5 + (it.dx || 0), y = it.y || 760; grond(ctx, w * i + 20, w * (i + 1) - 20, y);
      P.teken(ctx, x, y, s, Object.assign({ a: 0.9 }, it.o));
      omtrek(ctx, it.ref, P, x, y, s, it.rust ? { x0: P.D.X0 + (P.D.anker || 0) * P.D.K } : { neus: neusX(P, it.o) });
      label(ctx, it.naam, x, y + 50); }); }
  function strip(ctx, P, h, y, s, n = 8, o = {}) { const w = 1920 / n; for (let i = 0; i < n; i++) { const t = (o.t0 || 0) + i / n; const x = w * i + w * 0.5 + (o.dx || 0) * s;
      grond(ctx, w * i + 8, w * (i + 1) - 8, y); P.teken(ctx, x, y, s, { houding: h, t }); const I = P.info({ houding: h, t });
      for (const L of ['V', 'VF', 'A', 'AF']) { const v = I.voeten[L]; if (!v) continue; const px = x + (v.teen[0] - (P.D.anker || 0)) * s;
        if (v.steun) { ctx.strokeStyle = L.length > 1 ? 'rgba(120,200,255,0.75)' : 'rgba(255,120,90,0.85)'; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(px, y + 6); ctx.lineTo(px, y + 26); ctx.stroke(); }
        if (v.rek > 1.005) { ctx.fillStyle = '#FF3030'; ctx.beginPath(); ctx.arc(px, y - 4, 5, 0, 6.283); ctx.fill(); } }
      label(ctx, 't=' + t.toFixed(3), x, y + 52, '#8C97AE', 18); } }
  function delen(ctx, P, lijst, x0, y0, s, titel) { bg(ctx, titel); ctx.save(); ctx.translate(x0, y0); ctx.scale(s, s);
    for (const [k, dx, dy] of lijst) { const pv = P.deel(ctx, k, dx, dy); ctx.fillStyle = '#FF5A5A'; for (const p of pv) { ctx.beginPath(); ctx.arc(p[0], p[1], 0.9, 0, 6.283); ctx.fill(); } }
    ctx.restore(); }
  function zoom(ctx, P, o, cx, cy, k, vak, s0 = 4) { // vak = [x, y, w, h] op het scherm; cx, cy = cm-punt in het midden
    ctx.save(); ctx.beginPath(); ctx.rect(...vak); ctx.clip(); ctx.fillStyle = '#1C2944'; ctx.fillRect(...vak);
    const s = s0 * k; P.teken(ctx, vak[0] + vak[2] / 2 - cx * s, vak[1] + vak[3] / 2 - cy * s, s, o); ctx.restore(); ctx.strokeStyle = '#5A6680'; ctx.lineWidth = 2; ctx.strokeRect(...vak); }
  return { bg, label, grond, omtrek, overlay, strip, delen, zoom, neusX };
})();

