// ---- film (render_film.py): 10 s, 24 fps; jachtluipaard stap -> galop, leeuw stap, tijger stap, huiskat stap -> zitten -> liggen ----
TV_pop_katten.film = (ctx, f) => { const fps = 24, t = f / fps; const H = 1080, W = 1920, gy = 900;
  const seg = [[0, 1.6, 'luipaard', 'lopen', 'jachtluipaard · stap'], [1.6, 4.2, 'luipaard', 'galop', 'jachtluipaard · galop (roterend, twee zweeffasen)'], [4.2, 6.2, 'leeuw', 'lopen', 'leeuw · stap'], [6.2, 8.0, 'tijger', 'lopen', 'tijger · stap'], [8.0, 10.5, 'huiskat', 'kat', 'huiskat · stap, zitten, liggen']];
  const S = seg.find(z => t >= z[0] && t < z[1]) || seg[seg.length - 1]; const [t0, t1, n, h, label] = S; const P = KAT[n]; const ts = t - t0;
  const pxcm = { luipaard: 5.6, leeuw: 3.5, tijger: 4.0, huiskat: 15 }[n];
  const freq = { lopen: { luipaard: 1.0, leeuw: 0.85, tijger: 0.9, huiskat: 1.5 }[n], galop: 2.4 }[h] || 1;
  let snel = 0, st = null, kijk = 1;
  if (h === 'lopen' || h === 'galop') { const fase = ts * freq; snel = P.SNELHEID[h] * freq; st = P.stand({ houding: h, t: fase }); }
  else { const tw = ts; const hs = tw < 1.1 ? null : (tw < 1.7 ? ['staan', 'zitten', (tw - 1.1) / 0.6] : (tw < 1.95 ? ['zitten', 'zitten', 1] : ['zitten', 'liggen', Math.min(1, (tw - 1.95) / 0.5)]));
    if (!hs) { snel = P.SNELHEID.lopen * 1.5 * Math.max(0, 1 - tw / 1.1); st = P.stand({ houding: 'lopen', t: tw * 1.5 * (1 - tw / 2.2) }); }
    else { const a = P.stand({ houding: hs[0] }), b = P.stand({ houding: hs[1] }); const u = hs[2] * hs[2] * (3 - 2 * hs[2]); st = P.meng(a, b, u); } }
  // achtergrond: nacht-savanne die meeschuift
  ctx.fillStyle = '#1E2A47'; ctx.fillRect(0, 0, W, H); ctx.fillStyle = '#243656'; ctx.fillRect(0, gy - 260, W, 260);
  const scroll = (snel * ts * pxcm) % 600, scroll2 = (snel * ts * pxcm * 0.35) % 900;
  ctx.fillStyle = '#2B3E5E'; for (let i = -1; i < 4; i++) { const x = i * 900 - scroll2; ctx.beginPath(); ctx.ellipse(x + 300, gy - 240, 260, 60, 0, Math.PI, 0); ctx.fill(); }
  ctx.fillStyle = '#3B5240'; ctx.fillRect(0, gy, W, H - gy);
  ctx.fillStyle = '#2F4434'; for (let i = -1; i < 5; i++) { const x = i * 600 - scroll; for (let k = 0; k < 6; k++) { const xx = x + k * 97 + (k % 2) * 30, yy = gy + 30 + (k * 37) % 120; ctx.beginPath(); ctx.ellipse(xx, yy, 46, 7, 0, 0, 6.283); ctx.fill(); } }
  ctx.strokeStyle = '#4C6650'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(0, gy); ctx.lineTo(W, gy); ctx.stroke();
  if (n === 'huiskat' && ts > 1.1) { // staan -> (overvloei) zitten-figuur -> (overvloei) liggen
    const u1 = Math.min(1, Math.max(0, (ts - 1.25) / 0.45)), u2 = Math.min(1, Math.max(0, (ts - 2.0) / 0.4));
    if (u1 < 1) P.teken(ctx, 960, gy, pxcm, { houding: 'staan', a: 1 - u1 }); if (u1 > 0 && u2 < 1) P.teken(ctx, 960, gy, pxcm, { houding: 'zitten', a: u1 * (1 - u2) }); if (u2 > 0) P.teken(ctx, 960, gy, pxcm, { houding: 'liggen', a: u2 });
  } else P.teken(ctx, 960, gy, pxcm, { stand: st, kijk });
  ctx.fillStyle = '#E8E2D6'; ctx.font = '600 40px "Source Sans 3", sans-serif'; ctx.textAlign = 'left'; ctx.fillText(label, 70, 90); };
TV_pop_katten.kat_zit = (ctx) => { const P = KAT.huiskat; KTV.bg(ctx, 'Huiskat zitten en liggen (groot) op de plaat');
  for (const [h, r, x] of [['zitten', 'kat_zitten', 480], ['liggen', 'kat_liggen', 1380]]) { const o = { houding: h }; KTV.grond(ctx, x - 420, x + 420, 950); P.teken(ctx, x, 950, 17, Object.assign({ a: 0.85, skelet: 1 }, o)); KTV.omtrek(ctx, r, P, x, 950, 17, { neus: KTV.neusX(P, o) }); } };
